      premises: [],
      formula: String.raw`H^k(X,\mathbb C) = \bigoplus_{p+q=k} H^{p,q}(X),\qquad \overline{H^{p,q}} = H^{q,p},\qquad H^{p,q} \cong H^q(X,\Omega^p_X)`,
